create table onboarding_plans(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null unique references customer_accounts(id) on delete cascade,status text not null check(status in('not_started','in_progress','completed','paused')),template_version text not null,owner_id uuid references internal_users(id),started_at timestamptz,setup_completed_at timestamptz,target_activation_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table onboarding_steps(id uuid primary key default gen_random_uuid(),onboarding_plan_id uuid not null references onboarding_plans(id) on delete cascade,step_key text not null,title text not null,position int not null check(position>0),required boolean not null default true,status text not null check(status in('pending','completed','skipped')),completed_at timestamptz,completed_by uuid references internal_users(id),unique(onboarding_plan_id,step_key),unique(onboarding_plan_id,position),check(status<>'completed' or completed_at is not null));
create table activation_criteria(id uuid primary key default gen_random_uuid(),onboarding_plan_id uuid not null references onboarding_plans(id) on delete cascade,criterion_key text not null,title text not null,event_name text not null,threshold int not null default 1 check(threshold>0),required boolean not null default true,unique(onboarding_plan_id,criterion_key));
create table customer_value_events(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null references customer_accounts(id) on delete cascade,event_name text not null,event_key text not null unique,occurred_at timestamptz not null,recorded_by uuid not null references internal_users(id),created_at timestamptz not null default now());
create table activation_snapshots(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null unique references customer_accounts(id) on delete cascade,criteria_results jsonb not null,activated_at timestamptz,first_value_at timestamptz,time_to_value_seconds bigint,computed_at timestamptz not null,check(time_to_value_seconds is null or time_to_value_seconds>=0));
alter table onboarding_plans enable row level security;alter table onboarding_steps enable row level security;alter table activation_criteria enable row level security;alter table customer_value_events enable row level security;alter table activation_snapshots enable row level security;
grant select,insert,update on onboarding_plans,onboarding_steps,activation_criteria,customer_value_events,activation_snapshots to authenticated;
create policy onboarding_plans_select on onboarding_plans for select using(is_active_internal_user());create policy onboarding_plans_write on onboarding_plans for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy onboarding_steps_select on onboarding_steps for select using(is_active_internal_user());create policy onboarding_steps_write on onboarding_steps for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy activation_criteria_select on activation_criteria for select using(is_active_internal_user());create policy activation_criteria_write on activation_criteria for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy customer_value_events_select on customer_value_events for select using(is_active_internal_user());create policy customer_value_events_write on customer_value_events for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy activation_snapshots_select on activation_snapshots for select using(is_active_internal_user());create policy activation_snapshots_write on activation_snapshots for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
